import numpy as np, json, math

drivers = ["NOR","PIA","RUS","ANT","VER","LAW","LEC","HAM","ALB","SAI","LIN","TSU","STR","ALO","OCO","BEA","HUL","BOR","GAS","COL","PER","BOT"]
# grid positions (1-indexed)
grid = {"NOR":1,"ANT":2,"VER":3,"HAM":4,"LEC":5,"RUS":6,"PIA":7,"LAW":8,"COL":9,"LIN":10,"HUL":11,"BOR":12,"OCO":13,"GAS":14,"TSU":15,"ALB":16,"ALO":17,"PER":18,"BOT":19,"SAI":20,"BEA":21,"STR":22}

# Pace gaps (s/lap relative to theoretical fastest). Tune.
pace = {
 "RUS": 0.00,
 "ANT": 0.08,
 "VER": 0.13,
 "NOR": 0.28,
 "HAM": 0.50,
 "LEC": 0.60, # old engine
 "PIA": 0.65,
 "LAW": 0.85,
 "OCO": 0.95, # Haas strong long run
 "BEA": 1.05,
 "LIN": 1.20,
 "COL": 1.25,
 "HUL": 1.30,
 "BOR": 1.35,
 "GAS": 1.40,
 "TSU": 1.55,
 "ALB": 2.00,
 "SAI": 2.05,
 "ALO": 2.20,
 "STR": 2.35,
 "PER": 2.45,
 "BOT": 2.60,
}

retire_base = {
 "NOR":0.10,"ANT":0.08,"VER":0.10,"HAM":0.10,"LEC":0.12,"RUS":0.09,"PIA":0.10,"LAW":0.14,
 "COL":0.18,"LIN":0.20,"HUL":0.15,"BOR":0.16,"OCO":0.15,"GAS":0.15,"TSU":0.16,
 "ALB":0.22,"ALO":0.20,"PER":0.24,"BOT":0.26,"SAI":0.22,"BEA":0.22,"STR":0.28,
}
# add 0.02 for street circuit
for k in retire_base:
    retire_base[k]+=0.02

dns_base = {d:0.003 for d in drivers}
dns_base["BEA"]=0.04
dns_base["STR"]=0.03
dns_base["SAI"]=0.004  # penalty? no
dns_base["ALB"]=0.005 # damage?
# Stroll water pressure, Bearman crash repair
dsq_base = {d:0.002 for d in drivers}

# Simulation params
PENALTY_PER_POS = 9.0  # seconds per grid position
NOISE_STD = 7.0  # luck/strategy noise std per driver (seconds total)
PACE_NOISE_STD = 0.12 # s/lap variation per race per driver

def simulate_one(rng, penalty= PENALTY_PER_POS, noise_std=NOISE_STD, pace_noise=PACE_NOISE_STD):
    # DNS, DSQ
    dns = {}
    dsq = {}
    for d in drivers:
        dns[d] = rng.random() < dns_base[d]
        dsq[d] = rng.random() < dsq_base[d]
    # retire
    retire = {}
    retire_lap = {}
    for d in drivers:
        if dns[d]:
            retire[d]=False
            continue
        # DSQ drivers: still could retire? assume if DSQ, ignore retire? But DSQ separate. For simplicity, DSQ overrides.
        # Retire prob
        p = retire_base[d]
        # extra first lap risk for midfield bunch? add small
        # if starting 8-16, +0.02 crash
        if 8 <= grid[d] <= 16 and rng.random()<0.02:
            p+=0.05
        r = rng.random() < p
        retire[d]=r
        if r:
            # lap of retire: 25% in first 5 laps, else uniform 6-57
            if rng.random()<0.25:
                lap = rng.integers(1,6)
            else:
                lap = rng.integers(6,58)
            retire_lap[d]=int(lap)
        else:
            retire_lap[d]=None
    # determine NC vs classified for retirees: if lap>=52 classified, else NC
    nc = {}
    for d in drivers:
        if dns[d] or dsq[d]:
            nc[d]=False
        elif retire[d]:
            lap = retire_lap[d]
            if lap>=52:
                nc[d]=False # classified despite retire
            else:
                nc[d]=True
        else:
            nc[d]=False
    # For classified drivers (started, not dns, not dsq, not nc): compute total time and rank
    # Includes finishers + late retirees (classified)
    classified_drivers = [d for d in drivers if not dns[d] and not dsq[d] and not nc[d]]
    # pace draw with noise
    total = {}
    for d in classified_drivers:
        # pace variation
        p = pace[d] + rng.normal(0, pace_noise)
        # total time
        t = p*57 + grid[d]*penalty + rng.normal(0, noise_std)
        # late retiree penalty? They retired late, so should be behind finishers who completed all laps? In F1, if you retire on lap 55, you are behind anyone who finishes 57 laps, even if you were ahead? Actually classification: finishers first, then retirees by laps completed. So late retirees should rank behind all finishers. Implement: add large penalty for retirees? But if multiple late retirees, order by lap? Simplify: add 100 + (57-lap)*10 ?
        if retire[d]:
            # classified retiree: behind finishers
            t += 200 + (57 - retire_lap[d])*5  # ensures behind, later retire better
        total[d]=t
    # sort ascending
    classified_drivers_sorted = sorted(classified_drivers, key=lambda d: total[d])
    # assign positions 1..len
    pos = {}
    for idx, d in enumerate(classified_drivers_sorted, start=1):
        pos[d]=idx
    # for non-classified, pos None
    for d in drivers:
        if d not in pos:
            pos[d]=None
    return {"dns":dns,"dsq":dsq,"retire":retire,"nc":nc,"pos":pos,"retire_lap":retire_lap}

def run(n=200000, penalty=9.0, noise_std=7.0, pace_noise=0.12, seed=0):
    rng = np.random.default_rng(seed)
    # counts
    win_counts = {d:0 for d in drivers}
    podium_counts = {d:0 for d in drivers}
    points_counts = {d:0 for d in drivers} # top10?
    # Actually points top10? 2026 points? Assume top10? Or top12 with 22 cars? 2026 still top10? Need check. Assume top10.
    pos_counts = {d:[0]*22 for d in drivers}
    nc_counts={d:0 for d in drivers}
    dns_counts={d:0 for d in drivers}
    dsq_counts={d:0 for d in drivers}
    retire_counts={d:0 for d in drivers}
    for i in range(n):
        res = simulate_one(rng, penalty, noise_std, pace_noise)
        for d in drivers:
            if res["dns"][d]:
                dns_counts[d]+=1
            elif res["dsq"][d]:
                dsq_counts[d]+=1
            elif res["nc"][d]:
                nc_counts[d]+=1
            else:
                p = res["pos"][d]
                pos_counts[d][p-1]+=1
                if p==1:
                    win_counts[d]+=1
                if p<=3:
                    podium_counts[d]+=1
                if p<=10:
                    points_counts[d]+=1
            if res["retire"][d]:
                retire_counts[d]+=1
    # print
    print(f"penalty={penalty} noise={noise_std} pace_noise={pace_noise} n={n}")
    for d in sorted(drivers, key=lambda x: win_counts[x], reverse=True):
        print(f"{d:3s} grid{grid[d]:2d} pace{pace[d]:.2f} Win{win_counts[d]/n:.3f} Pod{podium_counts[d]/n:.3f} Pts{points_counts[d]/n:.3f} Ret{retire_counts[d]/n:.3f} NC{nc_counts[d]/n:.3f} DNS{dns_counts[d]/n:.4f}")
    # occupancy
    occ = [sum(pos_counts[d][i] for d in drivers)/n for i in range(22)]
    print("occupancy:", [f"{o:.3f}" for o in occ])
    return win_counts, pos_counts, nc_counts, dns_counts, dsq_counts, retire_counts

run(n=100000, penalty=9.0, noise_std=7.0, pace_noise=0.12)

